import json

slug = (params.get("practice_slug") or "").strip()
problem = ""
settings = {}

def read_json(path):
    try:
        raw = api.files.read(file=path, scope="org")
    except Exception as exc:
        return None, "Couldn't read " + path + ": " + str(exc)
    try:
        return json.loads(raw), None
    except Exception as exc:
        return None, path + " isn't valid JSON (" + str(exc) + ")"

# No slug set (the param ships blank and can't be edited in the app): use
# the practice settings file, as long as there's exactly one.
if not slug:
    try:
        practice_entries = api.files.list(path="PracticeManager/Practices", scope="org") or []
    except Exception:
        practice_entries = []
    practice_slugs = []
    for e in practice_entries:
        name = str((e.get("name") if isinstance(e, dict) else e) or "").split("/")[-1]
        if name.endswith(".json"):
            practice_slugs.append(name[: -len(".json")])
    if len(practice_slugs) == 1:
        slug = practice_slugs[0]

if not slug:
    problem = "No practice_slug configured for this automation, and there isn't exactly one practice settings file in PracticeManager/Practices to fall back on."
else:
    found, err = read_json("PracticeManager/Practices/" + slug + ".json")
    if found is None:
        problem = err or ("No practice settings file found for slug '" + slug + "'.")
    else:
        settings = found

state = {"handled_keys": []}
if slug and not problem:
    found_state, _ = read_json("PracticeManager/State/" + slug + "-referral-watchdog.json")
    state = found_state or {"handled_keys": []}

import json
import datetime

def invoke(server, tool, args):
    return api.connectors.invoke(server=server, tool=tool, args=args) or {}

def link_id(obj, key):
    link = ((obj.get(key) or {}).get("links") or {}).get("self") or ""
    return link.rstrip("/").split("/")[-1] if link else ""

def parse(iso_str):
    return datetime.datetime.fromisoformat(iso_str.replace("Z", "+00:00"))

def zulu(dt):
    return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

def is_live(a):
    return not a.get("cancelled_at") and not a.get("archived_at") and not a.get("deleted_at")

slug = str(params["slug"] or "")
settings = params["settings"] or {}
state = params["state"] or {}
tz_name = str(settings.get("timezone") or "UTC")

# A practice can override any of these via "referral_watchdog" in its
# settings file.
cfg = settings.get("referral_watchdog") or {}
expiry_days = int(cfg.get("expiry_days", 21))
sessions_left_threshold = int(cfg.get("sessions_left", 1))
lookahead_days = int(cfg.get("lookahead_days", 28))

now = datetime.datetime.now(datetime.timezone.utc)
try:
    from zoneinfo import ZoneInfo
    today = now.astimezone(ZoneInfo(tz_name)).date()
except Exception:
    today = now.date()
lookahead_end = now + datetime.timedelta(days=lookahead_days)

def format_local(iso_str, fmt="%a %d %b, %I:%M %p"):
    try:
        from zoneinfo import ZoneInfo
        return parse(iso_str).astimezone(ZoneInfo(tz_name)).strftime(fmt).replace(" 0", " ").lstrip("0")
    except Exception:
        return iso_str

def format_date(date_str):
    try:
        return datetime.date.fromisoformat(date_str[:10]).strftime("%d %b %Y").lstrip("0")
    except Exception:
        return date_str

def referral_kind(c):
    rtype = str(c.get("referral_type") or "").lower()
    if rtype == "dva":
        return "DVA"
    if rtype == "medicare":
        return "Medicare"
    if not c.get("referral"):
        return ""
    name = str(c.get("name") or "").lower()
    if "dva" in name:
        return "DVA"
    if "medicare" in name:
        return "Medicare"
    return "Referral"

handled = set(str(k) for k in (state.get("handled_keys") or []) if k)

# 1. Open referral cases: Medicare / DVA by referral_type, or any case marked
# as a referral where Cliniko has no referral type (non-Australian accounts).
# Reading all cases and filtering here avoids relying on Cliniko's enum filter
# syntax, and keeps EXPIRED referrals in: Cliniko's "active" case list leaves
# them out, yet a patient still booked on an expired referral is the riskiest
# case of all.
cases = []
cases_checked = 0
page = 1
while page <= 5:
    res = invoke("cliniko-patients", "list_patient_cases", {"sort": "updated_at:desc", "per_page": 100, "page": page})
    batch = res.get("patient_cases") or []
    cases_checked += len(batch)
    for c in batch:
        if referral_kind(c) and not c.get("archived_at") and not c.get("closed_at"):
            cases.append(c)
    if len(batch) < 100:
        break
    page += 1

# 2. Sessions used and booked against each, and the patient's next booking.
at_risk = []
for c in cases:
    case_id = str(c.get("id") or "")
    patient_id = link_id(c, "patient")
    if not case_id or not patient_id:
        continue
    issue_date = str(c.get("issue_date") or "")
    expiry_date = str(c.get("expiry_date") or "")
    max_sessions = c.get("max_sessions")
    count_dna = bool(c.get("include_dna_attendees"))

    since = issue_date[:10] + "T00:00:00Z" if issue_date else zulu(now - datetime.timedelta(days=400))
    appts = []
    p = 1
    while p <= 3:
        res = invoke("cliniko-scheduling", "list_individual_appointments", {
            "patient_id": patient_id, "q": ["starts_at:>=" + since], "sort": "starts_at:asc", "per_page": 100, "page": p,
        })
        batch = res.get("individual_appointments") or []
        appts += batch
        if len(batch) < 100:
            break
        p += 1

    used = 0
    booked = 0
    next_booking = None
    future_live = []
    for a in appts:
        if not is_live(a):
            continue
        try:
            start = parse(str(a.get("starts_at") or ""))
        except Exception:
            continue
        on_case = link_id(a, "patient_case") == case_id
        if start <= now:
            if on_case and (count_dna or not a.get("did_not_arrive")):
                used += 1
        else:
            future_live.append(start)
            if on_case:
                booked += 1
            if next_booking is None or start < next_booking:
                next_booking = start

    # Only patients who are actually coming in soon need chasing.
    if next_booking is None or next_booking > lookahead_end:
        continue

    reasons = []
    remaining = None
    if isinstance(max_sessions, int) and max_sessions > 0:
        remaining = max_sessions - used - booked
        if remaining <= sessions_left_threshold:
            reasons.append(("No sessions left" if remaining <= 0 else str(remaining) + " session" + ("" if remaining == 1 else "s") + " left")
                           + " (" + str(used) + " used, " + str(booked) + " booked, of " + str(max_sessions) + ")")
    days_left = None
    bookings_after_expiry = 0
    if expiry_date:
        try:
            expiry = datetime.date.fromisoformat(expiry_date[:10])
            days_left = (expiry - today).days
            bookings_after_expiry = len([s for s in future_live if s.date() > expiry])
            if days_left < 0:
                reasons.append("Expired " + format_date(expiry_date))
            elif days_left <= expiry_days:
                reasons.append("Expires " + format_date(expiry_date) + " (in " + str(days_left) + " day" + ("" if days_left == 1 else "s") + ")")
            elif next_booking.date() > expiry:
                reasons.append("Expires " + format_date(expiry_date) + ", before the next booking")
        except Exception:
            pass
    if bookings_after_expiry:
        reasons.append(str(bookings_after_expiry) + " booking(s) after the expiry date would be unfunded")
    if not reasons:
        continue

    at_risk.append({
        "key": case_id + ":" + expiry_date + ":" + str(max_sessions or ""),
        "case_id": case_id,
        "case_name": str(c.get("name") or ""),
        "referral_type": referral_kind(c),
        "patient_id": patient_id,
        "contact_id": link_id(c, "contact"),
        "issue_date": issue_date,
        "issue_label": format_date(issue_date) if issue_date else "",
        "expiry_date": expiry_date,
        "expiry_label": format_date(expiry_date) if expiry_date else "",
        "days_left": days_left,
        "max_sessions": max_sessions if isinstance(max_sessions, int) else None,
        "used": used,
        "booked": booked,
        "remaining": remaining,
        "bookings_after_expiry": bookings_after_expiry,
        "next_booking_at": zulu(next_booking),
        "next_booking_label": format_local(zulu(next_booking)),
        "reasons": reasons,
    })

# 3. Names (and the GP contact) for the ones worth reporting.
for r in at_risk[:30]:
    try:
        p = invoke("cliniko-patients", "get_patient", {"id": r["patient_id"]})
    except Exception:
        p = {}
    r["patient_name"] = (str(p.get("first_name") or "") + " " + str(p.get("last_name") or "")).strip() or "Patient " + str(r["patient_id"])
    r["patient_first_name"] = str(p.get("preferred_first_name") or p.get("first_name") or "")
    r["patient_email"] = str(p.get("email") or "")
    r["gp_name"] = ""
    r["gp_email"] = ""
    if r["contact_id"]:
        try:
            ct = invoke("cliniko-patients", "get_contact", {"id": r["contact_id"]})
            r["gp_name"] = (" ".join(str(ct.get(k) or "") for k in ("title", "first_name", "last_name")).strip()
                            or str(ct.get("company_name") or ""))
            r["gp_email"] = str(ct.get("email") or "")
        except Exception:
            pass

# New ones only get a WorkQ item; a renewed referral (new expiry or session
# count) has a different key, so it's checked afresh.
flagged = [r for r in at_risk[:30] if r["key"] not in handled][:10]

# For #10 morning brief: every referral currently running out, raised or not.
try:
    api.files.put(
        file="PracticeManager/State/" + slug + "-referral-watchdog-summary.json",
        content=json.dumps({"generated_at": zulu(now), "at_risk": [{
            k: r.get(k) for k in ("patient_name", "referral_type", "case_name", "expiry_date", "remaining",
                                  "next_booking_label", "reasons")
        } for r in at_risk[:30]]}, indent=2, sort_keys=True),
        scope="org",
    )
except Exception:
    pass

summary = ("Checked " + str(cases_checked) + " cases; " + str(len(cases)) + " referrals; "
           + str(len(at_risk)) + " running out with a booking in the next " + str(lookahead_days) + " days; "
           + str(len(flagged)) + " newly raised.")
